/**
 * FIFO-capped event_id dedupe for Slack Events API / Socket Mode.
 * One instance per channel mount — not process-global.
 */
const DEFAULT_CAP = 2_000;
export function createEventIdDedupe(cap = DEFAULT_CAP) {
    const handled = new Set();
    return {
        tryHandle(eventId) {
            if (handled.has(eventId)) {
                return false;
            }
            handled.add(eventId);
            if (handled.size > cap) {
                const first = handled.values().next().value;
                if (first !== undefined) {
                    handled.delete(first);
                }
            }
            return true;
        },
    };
}
